import os
import html
import subprocess
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('notes-kb')
CONFLUENCE_BASE_URL = os.environ.get('CONFLUENCE_BASE_URL', 'https://example.atlassian.net/wiki')

@mcp.tool()
def publish_note_to_confluence(space_key: str, page_title: str, note_markdown_content: str, parent_page_id: str='') -> str:
    paragraphs_as_html = []
    for single_paragraph in note_markdown_content.split('\n\n'):
        escaped_paragraph = html.escape(single_paragraph.strip())
        if escaped_paragraph:
            paragraphs_as_html.append('<p>' + escaped_paragraph.replace('\n', '<br/>') + '</p>')
    storage_format_body = ''.join(paragraphs_as_html)
    # Prefer a richer Markdown rendering via the local pandoc program when available
    try:
        pandoc_result = subprocess.run(['pandoc', '-f', 'markdown', '-t', 'html'], input=note_markdown_content, capture_output=True, text=True, timeout=20)
        if pandoc_result.returncode == 0 and pandoc_result.stdout.strip():
            storage_format_body = pandoc_result.stdout
    except (OSError, subprocess.SubprocessError):
        pass
    request_payload = {'type': 'page', 'title': page_title, 'space': {'key': space_key}, 'body': {'storage': {'value': storage_format_body, 'representation': 'storage'}}}
    if parent_page_id:
        request_payload['ancestors'] = [{'id': parent_page_id}]
    authentication_pair = (os.environ['CONFLUENCE_USER'], os.environ['CONFLUENCE_API_TOKEN'])
    api_response = requests.post(CONFLUENCE_BASE_URL + '/rest/api/content', json=request_payload, auth=authentication_pair, timeout=30)
    if api_response.status_code >= 400:
        return 'Confluence rejected the request: ' + api_response.text[:300]
    response_body = api_response.json()
    relative_page_link = response_body['_links']['webui']
    return CONFLUENCE_BASE_URL + relative_page_link
